{
  "correction_rules": [
    "Bias correction: Model consistently overestimates prices, especially in early forecast periods; reduce initial forecast by 1-2% for high sentiment (0.25 or above).",
    "Lag correction: Forecast tends to lag true price movements by 2-4 days; adjust for recent sentiment shifts to anticipate 1-2 day lead in price direction.",
    "Overshoot after spikes: After sharp price spikes (e.g., >5% from prior day), model overcorrects downward; apply a 0.5-1.0% upward bias to prevent premature reversal.",
    "Mean reversion: Model underestimates mean reversion in volatile periods; increase forecast by 0.5-1.5% for 3-5 day windows following strong sentiment or price divergence.",
    "Horizon-specific error: 30-day forecasts show persistent underestimation of peak prices; apply a 1-2% upward adjustment for days 15-25 of forecast horizon when sentiment is neutral or positive."
  ]
}
